import{_ as a,C as r,o as i,c as n,j as e,a as d,G as s,a3 as l}from"./chunks/framework.Bvm_liKL.js";const m=JSON.parse('{"title":"PowerPoint 联动指南","description":"ICC-CE 与 PowerPoint 的三条联动通路、加载项安装与放映时的墨迹行为","frontmatter":{"title":"PowerPoint 联动指南","description":"ICC-CE 与 PowerPoint 的三条联动通路、加载项安装与放映时的墨迹行为"},"headers":[],"relativePath":"cn/guide/ppt-guide.md","filePath":"cn/guide/ppt-guide.md"}'),p={name:"cn/guide/ppt-guide.md"};function c(P,t,h,C,u,g){const o=r("ArticleMetadata");return i(),n("div",null,[t[0]||(t[0]=e("h1",{id:"powerpoint-联动指南",tabindex:"-1"},[d("PowerPoint 联动指南 "),e("a",{class:"header-anchor",href:"#powerpoint-联动指南","aria-label":'Permalink to "PowerPoint 联动指南"'},"​")],-1)),s(o),t[1]||(t[1]=l('<p>ICC-CE 可以在放映幻灯片时随讲随写，并把每一页的墨迹分别记住。</p><h2 id="三条联动通路" tabindex="-1">三条联动通路 <a class="header-anchor" href="#三条联动通路" aria-label="Permalink to &quot;三条联动通路&quot;">​</a></h2><p>ICC-CE 并不依赖单一方式与 PowerPoint 通信，而是按可用性依次尝试：</p><table tabindex="0"><thead><tr><th>通路</th><th>原理</th><th>何时生效</th></tr></thead><tbody><tr><td><strong>COM 自动化</strong></td><td>直接创建 PowerPoint 应用程序对象</td><td>最常规的情况，PowerPoint 正常启动即可</td></tr><tr><td><strong>ROT / OLE</strong></td><td>从运行对象表中获取已存在的 PowerPoint 实例</td><td>COM 创建失败、或 PowerPoint 由其他程序先行启动时</td></tr><tr><td><strong>VSTO 加载项</strong></td><td>由加载项主动把放映事件推送给 ICC-CE</td><td>前两者被安全策略拦截，或需要更及时的翻页事件时</td></tr></tbody></table><p>程序会自动选择可用的一条，无需手动切换。若三条都不可用，工具栏中的 PPT 相关按钮不会出现。</p><h2 id="安装-vsto-加载项" tabindex="-1">安装 VSTO 加载项 <a class="header-anchor" href="#安装-vsto-加载项" aria-label="Permalink to &quot;安装 VSTO 加载项&quot;">​</a></h2><p>加载项不是必需品，但能显著提升翻页事件的实时性。安装步骤：</p><ol><li>完全退出 PowerPoint 与 ICC-CE</li><li>在 ICC-CE 设置中找到 PowerPoint 相关分区，启用加载项支持</li><li>重新启动 PowerPoint，在「文件 → 选项 → 加载项」中确认 ICC 加载项处于启用状态</li></ol><div class="warning custom-block"><p class="custom-block-title">加载项被禁用</p><p>Office 有时会因为启动缓慢而自动禁用加载项。若发现联动失效，请到 「文件 → 选项 → 加载项 → 管理：禁用项目」中把 ICC 加载项重新启用。</p></div><h2 id="放映时的行为" tabindex="-1">放映时的行为 <a class="header-anchor" href="#放映时的行为" aria-label="Permalink to &quot;放映时的行为&quot;">​</a></h2><p>进入幻灯片放映后：</p><ul><li>工具栏会出现<strong>上一页 / 下一页 / 页码</strong>等 PPT 专属按钮</li><li>在幻灯片上书写的墨迹按<strong>页码</strong>分别保存在内存中</li><li>翻页时自动收起当前页墨迹、恢复目标页墨迹</li><li>退出放映时，可根据设置自动把整份演示文稿的墨迹存盘</li></ul><div class="tip custom-block"><p class="custom-block-title">翻页与撤销</p><p>翻页动作本身不进入撤销栈。误翻页请用工具栏的翻页按钮回到原页，墨迹会自动恢复。</p></div><h2 id="墨迹的保存位置" tabindex="-1">墨迹的保存位置 <a class="header-anchor" href="#墨迹的保存位置" aria-label="Permalink to &quot;墨迹的保存位置&quot;">​</a></h2><p>放映过程中产生的墨迹默认保存在数据目录下的 <code>Saves</code> 文件夹中，按演示文稿名称分目录存放。 保存路径可在设置中通过自动保存相关选项调整，详见<a href="/website/cn/guide/files-and-data">配置文件与数据目录</a>。</p><div class="warning custom-block"><p class="custom-block-title">演示文稿改名</p><p>墨迹是按演示文稿名称关联的。重命名 pptx 文件后，之前保存的墨迹将无法自动匹配到新文件。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>放映了但工具栏没有出现 PPT 按钮</strong> 说明三条通路都没连上。请确认 PowerPoint 是桌面版（非 UWP / 网页版），并检查杀毒软件是否拦截了 COM 调用。</p><p><strong>翻页时墨迹串页</strong> 多见于同时打开多份演示文稿的场景。请只放映一份，或退出后重新进入放映。</p><p><strong>墨迹没有自动保存</strong> 检查设置中自动保存是否开启，以及目标目录是否有写入权限（部分机房把安装目录设为只读）。</p>',20))])}const _=a(p,[["render",c]]);export{m as __pageData,_ as default};
